import path from "node:path";

export const apiMountGeneratedComment =
  "// Generated by scripts/generate-deployable-api-mounts.mjs. Do not edit by hand.\n";
export const apiMountGeneratedFileMarker = `${apiMountGeneratedComment}\n`;

export const deployableApiMountConfig = {
  "catalog-api": {
    fileParts: ["deployables", "catalog-api", "src", "context-api-mounts.generated.ts"],
  },
  "identity-api": {
    fileParts: ["deployables", "identity-api", "src", "context-api-mounts.generated.ts"],
  },
  "inventory-api": {
    fileParts: ["deployables", "inventory-api", "src", "context-api-mounts.generated.ts"],
  },
  "marketplace-api": {
    fileParts: ["deployables", "marketplace-api", "src", "context-api-mounts.generated.ts"],
  },
};

function toPascalCase(value) {
  return value
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((segment) => segment[0].toUpperCase() + segment.slice(1))
    .join("");
}

export function resolveDeployableApiMountPath(repoRoot, deployable) {
  const config = deployableApiMountConfig[deployable];
  if (!config) {
    throw new Error(`Unknown deployable API mount config: ${deployable}`);
  }

  return path.join(repoRoot, ...config.fileParts);
}

export function buildApiMountFileContent(contexts) {
  if (contexts.length === 0) {
    return `${apiMountGeneratedFileMarker}import type { ResolvedApiMount } from "@chase-sets/bounded-context-runtime";

export function createContextApiMounts(): readonly ResolvedApiMount[] {
  return [];
}
`;
  }

  const imports = contexts.map(({ contextName, packageName }) => {
    const alias = `resolve${toPascalCase(contextName)}ApiMounts`;
    return `import { resolveApiMounts as ${alias} } from "${packageName}";`;
  });

  const serviceType =
    contexts.length === 1
      ? `Parameters<typeof resolve${toPascalCase(contexts[0].contextName)}ApiMounts>[0]`
      : `{
  ${contexts
    .map(
      ({ contextName }) =>
        `${contextName}: Parameters<typeof resolve${toPascalCase(contextName)}ApiMounts>[0];`,
    )
    .join("\n  ")}
}`;

  const body =
    contexts.length === 1
      ? `  return resolve${toPascalCase(contexts[0].contextName)}ApiMounts(services);`
      : contexts
          .map(
            ({ contextName }) =>
              `    ...resolve${toPascalCase(contextName)}ApiMounts(services.${contextName}),`,
          )
          .join("\n");

  return `${apiMountGeneratedFileMarker}import type { ResolvedApiMount } from "@chase-sets/bounded-context-runtime";
${imports.join("\n")}

export function createContextApiMounts(
  services: ${serviceType},
): readonly ResolvedApiMount[] {
${contexts.length === 1 ? body : `  return [\n${body}\n  ];`}
}
`;
}
